#include <stdio.h>

int main() {
    int addrs[] = {0, 1, 2, 3, 5, 7, 10, 13};
    int n = 8;
    printf("对齐到 4 字节边界（向下/向上取整到 4 的倍数）：\n");
    for (int i = 0; i < n; i++) {
        int aligned = (addrs[i] + 3) & ~3;   /* 向上对齐到 4 的倍数 */
        printf("  原地址 %2d -> 对齐地址 %2d (填充 %d 字节)\n",
               addrs[i], aligned, aligned - addrs[i]);
    }
    return 0;
}
